import os
import re

DEFAULT_DOTENV = ".env"

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Matches `KEY=...` with an optional leading `export ` keyword.
_LINE_RE = re.compile(r"^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=(.*)$")


def _parse_value(raw):
    raw = raw.strip()
    if raw[:1] in ("'", '"'):
        quote = raw[0]
        out = []
        i = 1
        while i < len(raw):
            ch = raw[i]
            if quote == '"' and ch == "\\" and i + 1 < len(raw) and raw[i + 1] in ('"', "\\"):
                out.append(raw[i + 1])
                i += 2
                continue
            if ch == quote:
                # Anything after the closing quote (such as a comment) is ignored.
                return "".join(out)
            out.append(ch)
            i += 1
        # Unclosed quote: keep the value as written rather than guessing.
        return raw
    # Unquoted: a `#` preceded by whitespace starts a comment.
    match = re.search(r"\s#", raw)
    if match:
        raw = raw[: match.start()]
    return raw.strip()


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            match = _LINE_RE.match(line)
            if match is None:
                continue
            values[match.group(1)] = _parse_value(match.group(2))
    return values


def load_config(environ=None, dotenv_path=DEFAULT_DOTENV):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config

